args.command:
CDP_DIR="$(readlink -f ~/.claude/skills/chrome-cdp-ex 2>/dev/null || true)"
echo "CDP_DIR=$CDP_DIR"
test -x "$CDP_DIR/bin/chrome-cdp" && echo "BIN_OK" || echo "BIN_MISSING"
"$CDP_DIR/bin/chrome-cdp" doctor --format json
echo "---GIT---"
git -C "$CDP_DIR" rev-parse --short HEAD 2>&1 || true
git -C "$CDP_DIR" remote get-url origin 2>&1 || true
echo "---VERSION---"
CDP_DIR="$CDP_DIR" node --input-type=module <<'EOF'
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
const min = [2, 21, 0];
let dir = process.env.CDP_DIR || "";
let version = "";
while (dir && dir !== dirname(dir)) {
  const file = join(dir, "package.json");
  if (existsSync(file)) {
    const pkg = JSON.parse(readFileSync(file, "utf8"));
    if (pkg.name === "pi-chrome-cdp") {
      version = String(pkg.version || "");
      break;
    }
  }
  dir = dirname(dir);
}
const parts = version.split(".").map((part) => Number.parseInt(part, 10) || 0);
let cmp = 0;
for (let i = 0; i < 3; i += 1) {
  cmp = (parts[i] || 0) - min[i];
  if (cmp !== 0) break;
}
if (!version || cmp < 0) {
  console.error(version
    ? `STOP: chrome-cdp-ex ${version} is below 2.21.0. Update to v2.21.0 or newer.`
    : "STOP: cannot read chrome-cdp-ex version. Need package.json name pi-chrome-cdp.");
  process.exit(1);
}
console.log(version);
EOF
node --version
date +%Y-%m-%d
ls -la <repo>/<run dir>/<node> 2>/dev/null || echo "NO_FRONTEND_QA_YET"

