args.command:
CDP="<repo>/<run dir>/<node>"
survey() {
  local url="$1"
  "$CDP" nav 4C9402F5 "$url" --compact ><repo>/<run dir>/<node> 2>&1 || true
  "$CDP" eval 4C9402F5 '(()=>{
    const vis=el=>{const r=el.getBoundingClientRect();return r.width>0&&r.height>0&&getComputedStyle(el).visibility!=="hidden"};
    const controls=[...document.querySelectorAll("a,button,input,select,textarea")].filter(vis).map(el=>({
      tag:el.tagName, type:el.type||"", name:el.name||"",
      text:(el.innerText||el.getAttribute("aria-label")||el.placeholder||"").replace(/\s+/g," ").slice(0,50),
      href:el.getAttribute("href")||"",
      w:Math.round(el.getBoundingClientRect().width), h:Math.round(el.getBoundingClientRect().height)
    }));
    const h=[...document.querySelectorAll("h1,h2,h3")].map(el=>el.tagName+":"+el.innerText.replace(/\s+/g," ").slice(0,80));
    const body=(document.body.innerText||"").replace(/\s+/g," ").slice(0,700);
    return JSON.stringify({url:location.hash,title:document.title,h,controls,body});
  })()'
  echo ""
}
for u in \
  "http://localhost:4173/#/orders/1" \
  "http://localhost:4173/#/orders/2" \
  "http://localhost:4173/#/orders/3" \
  "http://localhost:4173/#/orders/new" \
  "http://localhost:4173/#/settings" \
  "http://localhost:4173/#/help" \
  "http://localhost:4173/#/contact" \
  "http://localhost:4173/#/missing" \
  "http://localhost:4173/not-a-page"
 do
  echo "######## $u"
  survey "$u"
 done

