args.command:
CDP="<repo>/<run dir>/<node>"
echo "==== STRUCTURE ===="
"$CDP" eval 4C9402F5 '(()=>{
  function walk(el,d){
    if(!el||d>4) return null;
    if(el.tagName==="SCRIPT"||el.tagName==="STYLE") return null;
    const kids=[...el.children].map(c=>walk(c,d+1)).filter(Boolean);
    const t=(el.childNodes.length===1&&el.childNodes[0].nodeType===3)?el.textContent.trim().slice(0,40):"";
    return {tag:el.tagName,id:el.id||undefined,cls:el.className||undefined,t:t||undefined,kids:kids.length?kids:undefined};
  }
  return JSON.stringify(walk(document.body,0));
})()'
